  /* Navbar */
  initSideNav();
  navbarScrollBehavior();
  initMobileSideModeles();

  /* Popup Sales */
  popupSales();

  /* Map Concessions */
  initMap();

  /* CTA Concession cross-page */
  initConcessionCta();

  /* Comparateur */
  comparateurLogic();

  /* Sliders */
  initHomeHeroSlider();
  initServicesSlide();
  initOffresSlider();
  initModelesHeroSlider();
  initModelesInnerSlider();
  initBlogBannerSlider();

  /* Modèles: anchor fixed after 200vh */
  initAnchorPosition();

